// Phase F, T013/T014: `H$` system table of a dictionary column (POS_TO_ID, ID_TO_POS). Expected bytes are Desktop's own files
// from the probe table of `f1probe.pbix` (CSV loaded in Power BI Desktop 2.159, 2026-11-15, `docs/phase-f-evidence/vm-f1/`).
import Foundation
import Testing
@testable import PBIXKit

@Suite struct HierarchyEncodingTests {
    private func hex(_ data: Data) -> String { data.map { String(format: "%02x", $0) }.joined() }

    private func hierarchy(_ values: VertiPaqWriter.Values) throws -> VertiPaqWriter.EncodedHierarchy {
        let dictionary = try VertiPaqWriter.encodeDictionary(values)
        return try VertiPaqWriter.encodeHierarchy(sortedIDs: dictionary.sortedIDs, dictionaryCount: dictionary.count, hasNulls: dictionary.hasNulls)
    }

    /// Column S = b, a, c, a, d, b: four values, sorted a, b, c, d.
    @Test func chuoiBonGiaTriKhopFileDesktop() throws {
        let h = try hierarchy(.string(["b", "a", "c", "a", "d", "b"]))
        #expect(hex(h.positionToID.idf) == "0300000000000000040000000300000005000000060000000000000000000000020000000000000000000000000000000000000000000000")
        #expect(hex(h.idToPosition.idf) == "0300000000000000000000000400000000000000010000000000000000000000020000000000000000000000020000000300000000000000")
        #expect(h.cardinality == 4 && h.recordCount == 7)
    }

    /// Column N = x, "", y, x, y, "": three values (an empty string is a value, not NULL), sorted "", x, y. Also checks `.idfmeta`.
    @Test func chuoiBaGiaTriVaIdfmetaKhopFileDesktop() throws {
        let h = try hierarchy(.string(["x", "", "y", "x", "y", ""]))
        #expect(hex(h.positionToID.idf) == "020000000000000004000000030000000500000000000000020000000000000000000000000000000000000000000000")
        #expect(hex(h.idToPosition.idf) == "020000000000000000000000030000000000000000000000020000000000000001000000000000000200000000000000")
        #expect(hex(h.positionToID.idfmeta) == "")
        #expect(hex(h.idToPosition.idfmeta) == hex(h.positionToID.idfmeta))
    }

    /// Column T = dates 3, 1, 2, 3, 5, 4 (days): five values, first-appearance IDs 3 to 7.
    @Test func soNamGiaTriKhopFileDesktop() throws {
        let h = try hierarchy(.double([3, 1, 2, 3, 5, 4]))
        #expect(hex(h.positionToID.idf) == "0300000000000000040000000500000003000000070000000600000000000000020000000000000000000000000000000000000000000000")
        #expect(hex(h.idToPosition.idf) == "0300000000000000000000000500000000000000020000000000000000000000020000000000000001000000040000000300000000000000")
    }

    /// NULL has data ID 2 and sorts first. Layout as in the Marketing table of `tuan6.2.pbix` (Marketer: 6 names and NULL,
    /// IDs 2 to 8, record count 9). First-appearance IDs: d 3, b 4, e 5, a 6, f 7, c 8, so the sorted IDs are 2 (NULL), 6, 4, 8, 3, 5, 7.
    @Test func coNullIdLaHaiVaSapDauTien() throws {
        let h = try hierarchy(.string([nil, "d", "b", "e", "a", "f", "c"]))
        #expect(h.cardinality == 7 && h.recordCount == 9)
        let p2i = h.positionToID.idf
        #expect(p2i.count == 8 + 4 * 8 + 24)
        let ids = (0..<7).map { p2i.subdata(in: (8 + 4 * $0)..<(12 + 4 * $0)).withUnsafeBytes { $0.loadUnaligned(as: UInt32.self) } }
        #expect(ids == [2, 6, 4, 8, 3, 5, 7])
    }

    @Test func tuyetDoiKhongSinhFileSaiKichThuoc() throws {
        for count in [3, 4, 5, 50, 51, 1250] {   // một và hai giá trị cắt thành nhiều đoạn: có test riêng với byte của Desktop
            let h = try hierarchy(.int64((0..<count).map { Int64($0) }))
            #expect(h.positionToID.idf.count == 8 + 8 * (count / 2 + 1) + 24, Comment(rawValue: "card \(count)"))
            #expect(h.idToPosition.idf.count == h.positionToID.idf.count)
            #expect(h.positionToID.idfmeta.count == 316)
        }
    }

    /// Từ điển chuỗi có mục rỗng: tiêu đề trang đặt cờ "có chuỗi rỗng" (Desktop 2.159, bảng `probe2` nạp từ CSV; thiếu cờ này Desktop báo
    /// "DBCC failed while checking the string store"). Byte kỳ vọng là tệp `.dictionary` của Desktop.
    @Test func tuDienChuoiCoMucRongKhopDesktop() throws {
        let b = try VertiPaqWriter.encodeDictionary(.string(["x", "y", ""]))
        #expect(hex(b.data) == "")
        let a = try VertiPaqWriter.encodeDictionary(.string(["Đà Nẵng", "", "Huế", "", "Đà Nẵng"]))
        #expect(hex(a.data) == "")
        #expect(!hex(try VertiPaqWriter.encodeDictionary(.string(["x", "y"])).data).contains("0101000000000000000100000000000000000000000000000001"))   // không cờ khi không có mục rỗng
    }

    /// Cột chỉ có một hoặc hai giá trị: Desktop cắt mảng thành đoạn `card` dòng (4 đoạn, hoặc 3 đoạn 2+2+1), mỗi đoạn một khối trong `.idfmeta`
    /// và một cặp (độ lệch, số từ) ở phần đuôi. Byte kỳ vọng là tệp của Desktop (bảng `probe4`, 2026-11-15).
    @Test func motVaHaiGiaTriKhopFileDesktop() throws {
        let one = try hierarchy(.string(["a", "a", "a", "a"]))
        #expect(hex(one.positionToID.idf) == "01000000000000000300000000000000010000000000000000000000000000000100000000000000000000000000000001000000000000000000000000000000")
        #expect(hex(one.idToPosition.idf) == "01000000000000000000000000000000010000000000000001000000000000000100000000000000000000000000000001000000000000000000000000000000")
        #expect(hex(one.positionToID.idfmeta) == "")
        #expect(one.segmentCount == 4 && one.recordCount == 4)
        let two = try hierarchy(.string(["x", "y", "x", "y"]))
        #expect(hex(two.positionToID.idf) == "02000000000000000300000004000000000000000000000002000000000000000000000000000000000000000000000001000000000000000000000000000000")
        #expect(hex(two.idToPosition.idf) == "02000000000000000000000002000000000000000000000002000000000000000000000000000000000000000000000001000000000000000100000000000000")
        #expect(hex(two.positionToID.idfmeta) == "")
        #expect(two.segmentCount == 3 && two.recordCount == 5)
        let mixed = try hierarchy(.string(["a", "", "a", ""]))   // chuỗi rỗng sắp trước
        #expect(hex(mixed.positionToID.idf) == "02000000000000000400000003000000000000000000000002000000000000000000000000000000000000000000000001000000000000000000000000000000")
        #expect(hex(mixed.idToPosition.idf) == "02000000000000000000000002000000000000000000000002000000000000000000000001000000000000000000000001000000000000000000000000000000")
        // Ngày hằng (một giá trị) giống chuỗi hằng.
        let day = try hierarchy(.dateTime([46_023, 46_023, 46_023, 46_023]))
        #expect(hex(day.positionToID.idf) == hex(one.positionToID.idf) && hex(day.idToPosition.idf) == hex(one.idToPosition.idf))
    }
}
